const sech=(t,p,l)=>`<div class="sec-h rv"><div><h2>${t}</h2>${p?`<p>${p}</p>`:''}</div>${l?`<a class="more-link" href="${l[0]}">${l[1]} →</a>`:''}</div>`;
function tableHTML(g,ext){const R=ST[g];return`<div class="card rv"><div class="grp-h">Qrup ${g}<span>${DONE.length?esc(L.season)+' MÖVSÜMÜ':''}</span></div><div class="tw"><table class="t${ext?'':' sm'}"><thead><tr><th>#</th><th>Komanda</th><th>O</th><th>Q</th><th>H</th><th>M</th>${ext?'<th class="hm">VQ</th><th class="hm">BQ</th><th>TF</th>':''}<th>X</th>${ext?'<th class="hm">Forma</th>':''}</tr></thead><tbody>${R.map(r=>`<tr><td class="rk">${r.rank}</td><td class="tm"><a href="komanda.html?t=${r.id}">${ball(r.id,'sm')}<b>${esc(T[r.id].name)}</b></a></td><td>${r.o}</td><td>${r.q}</td><td>${r.h}</td><td>${r.m}</td>${ext?`<td class="hm">${r.vq}</td><td class="hm">${r.bq}</td><td class="${r.tf>0?'pos':r.tf<0?'neg':''}">${r.tf>0?'+':''}${r.tf}</td>`:''}<td class="x">${r.x}</td>${ext?`<td class="hm">${formHTML(r.id)}</td>`:''}</tr>`).join('')}</tbody></table></div></div>`}
function pageEnd(){
 const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target)}}),{threshold:.12});$$('.rv,.chart .col,.bar').forEach(e=>io.observe(e));
 $$('[data-count]').forEach(el=>{const to=+el.dataset.count,dec=+el.dataset.dec||0;const io2=new IntersectionObserver(es=>{if(es[0].isIntersecting){io2.disconnect();const t0=performance.now();(function f(t){const p=Math.min(1,(t-t0)/1200),v=to*(1-Math.pow(1-p,3));el.textContent=v.toFixed(dec);if(p<1)requestAnimationFrame(f)})(t0)}});io2.observe(el)});
 document.addEventListener('click',e=>{const b=e.target.closest('.mc-more');if(!b)return;const c=b.closest('.mc');c.classList.toggle('open');b.setAttribute('aria-expanded',c.classList.contains('open'));b.textContent=c.classList.contains('open')?'Bağla ▴':'Qol / kartlar ▾'});
 const cd=$('#cd');if(cd){const tg=new Date(cd.dataset.t).getTime();const tick=()=>{let s=Math.max(0,Math.floor((tg-Date.now())/1000));const v=[Math.floor(s/86400),Math.floor(s%86400/3600),Math.floor(s%3600/60),s%60];$$('b',cd).forEach((b,i)=>b.textContent=String(v[i]).padStart(2,'0'))};tick();setInterval(tick,1000)}
 if(location.hash){const el=document.getElementById(location.hash.slice(1));if(el&&el.classList.contains('mc')){el.classList.add('open');setTimeout(()=>el.scrollIntoView({behavior:'smooth',block:'center'}),400)}}}

