const fmtShort=d=>{if(!d)return '';const a=d.split('-');return `${a[2]}.${a[1]}.${a[0]}`};
const NEWS=(C.news||[]).slice().sort((a,b)=>b.date.localeCompare(a.date)),VIDEOS=(C.videos||[]).slice().sort((a,b)=>b.date.localeCompare(a.date));
const videoKind=v=>v.kind||'match';
const kindLabel=v=>({match:'Tam oyunlar',highlights:'Oyun icmalları',shorts:'Qısa videolar',program:'Liqadan'})[videoKind(v)];
const youtubeID=v=>/^[A-Za-z0-9_-]{11}$/.test(v.youtubeId||'')?v.youtubeId:'';
const thumb=v=>youtubeCoverURL(v)||siteLogo;
const videoForMatch=id=>VIDEOS.find(v=>v.match===id&&videoKind(v)==='match')||VIDEOS.find(v=>v.match===id);
const coverFallback=v=>videoCover({...v,coverMode:'poster'},{league:L,site:S,logo:siteLogo,translate:UI.t});
const renderCover=v=>videoCover(v,{league:L,site:S,logo:siteLogo,translate:UI.t});
const savedVideoKey='ssl.savedVideos.v1';let savedVideos=new Set();
try{const ids=JSON.parse(localStorage.getItem(savedVideoKey)||'[]');if(Array.isArray(ids))savedVideos=new Set(ids.filter(id=>typeof id==='string'&&VIDEOS.some(v=>v.id===id)));}catch{}
const isVideoSaved=id=>savedVideos.has(id);
const saveVideoButton=v=>`<button type="button" class="save-video ${isVideoSaved(v.id)?'saved':''}" data-save-video="${esc(v.id)}" aria-pressed="${isVideoSaved(v.id)}" aria-label="${UI.t('Videonu saxla')}"><span aria-hidden="true">${isVideoSaved(v.id)?'★':'☆'}</span></button>`;
let refreshVideoSaves=()=>{};
function newsArtwork(n){const v=videoForMatch(n.match),editorial=/^ssl-(?:season|round\d+|scorers)-?/.test(n.id),fallback=editorial||!v?editorialArtwork(n,{L,S,T,DONE,SC,B,esc,ball}):coverFallback(v);if(!n.image||!CMSKit.imagePath(n.image))return fallback;const fit=n.imageFit==='contain'?'contain':'cover',position=['top','bottom'].includes(n.imagePosition)?n.imagePosition:'center';return `<div class="news-photo-frame image-fit-${fit} image-position-${position}">${fallback}<img class="remote-cover news-photo" src="${esc(n.image)}" alt="${esc(n.title)}" loading="lazy" decoding="async"></div>`;}
function newsCard(n,featured=false){const ownSource=n.source===S.name||/^(Sumqayıt Super Liqası(?:sı)?|Sumg(?:ay|a)it Super League|Sumqayıt Super Liqası)$/.test(n.source||'');return `<a class="news-card ${featured?'featured':''}" href="xeberler.html?id=${encodeURIComponent(n.id)}"><div class="news-art news-art-photo">${newsArtwork(n)}</div><div class="news-copy"><span class="news-meta"><span class="news-category">${esc(n.category)}</span><time datetime="${esc(n.date)}">${fmtShort(n.date)}</time>${ownSource?'':' <i></i> '+esc(n.source)}</span><h3>${esc(n.title)}</h3></div></a>`;}
function videoCard(v,i=0){const m=M.find(m=>m.id===v.match);return `<article class="video-card"><div class="video-visual"><a class="video-thumbnail" target="_blank" rel="noopener noreferrer" href="${esc(v.url)}" aria-label="${esc(v.label||v.title)} videosunu YouTube-da izlə">${renderCover(v)}<span class="thumbnail-play" aria-hidden="true">▶</span></a>${saveVideoButton(v)}</div><div class="video-content"><div class="video-overline">${m?UI.t(matchLabel(m))+' · ':''}${v.date?fmtShort(v.date)+' · ':''}SSL TV</div><h3>${esc(v.label||v.title)}</h3><div class="video-links"><a target="_blank" rel="noopener noreferrer" href="${esc(v.url)}">Videonu izlə ↗</a>${m?`<a href="matc.html?id=${encodeURIComponent(v.match)}">Matç statistikası →</a>`:''}</div></div></article>`;}
function homePulse(){return`<section class="pulse"><div class="wrap pulse-inner"><div class="pulse-title"><span class="live-dot"></span> LİQANIN NƏBZİ <small>/ ${esc(L.season)} MÖVSÜMÜ</small></div><div class="pulse-values"><a href="oyunlar.html">${DONE.length} <span>OYUN</span></a><a href="statistika.html">${DONE.reduce((x,m)=>x+m.hs+m.as,0)} <span>QOL</span></a><a href="komandalar.html">${L.teams.length} <span>KOMANDA</span></a><a href="bombardirler.html">${SC[0]?SC[0].g:0} <span>LİDER QOL</span></a></div></div></section>`}
function homeMedia(){const chosen=VIDEOS.filter(v=>videoKind(v)==='match').slice(0,H.videoLimit??3);if(!chosen.length)return '';return `<section class="sec pro-media-home"><div class="wrap">${sech('SSL TV / Matç arxivi','Tam oyunlar və seçilmiş anlar',['media.html','Bütün videolar'])}<div class="video-grid">${chosen.map(videoCard).join('')}</div></div></section>`;}
function homeNews(){const featured=NEWS.find(n=>n.id===H.featuredNews)||NEWS[0],top=new Set([featured,...NEWS.filter(n=>n!==featured).slice(0,2)].filter(Boolean).map(n=>n.id)),selected=NEWS.filter(n=>!top.has(n.id)).slice(0,H.newsLimit??3);if(!selected.length)return '';return `<section class="sec editorial-home"><div class="wrap">${sech('Liqanın gündəmi','Xəbərlər və oyun icmalları',['xeberler.html','Bütün xəbərlər'])}<div class="news-grid">${selected.map(n=>newsCard(n)).join('')}</div></div></section>`;}
function findPlayerGoals(team,name){return DONE.flatMap(m=>m.goals.filter(g=>!g.og&&!g.unk&&g.t===team&&tok(g.p)===tok(name)).map(g=>({m,g})))}
function playerLink(t,p){p=T[t]?.players.find(x=>tok(x.name)===tok(p))?.name||p;return`futbolcu.html?t=${encodeURIComponent(t)}&p=${encodeURIComponent(p)}`}
function playerBadge(p){return p.gk?'QAPIÇI':'OYUNÇU'}

